async function flags(){return backend.readRpc('app_finance_v2_flags_v143',{p_club_id:cid()})}
async function qaStatus(){return backend.readRpc('app_finance_v2_qa_status_v146',{p_club_id:cid()})}
async function pilotStatus(){return backend.readRpc('app_finance_pilot_readiness_v148',{p_club_id:cid()})}
export async function shouldUseFinancePremium(){if(!cid()||!manager())return false;try{const f=await flags();return f?.finance_v2_enabled===true&&f?.finance_dashboard_v2_enabled===true}catch(error){const raw=String(error?.message||error||'');if(/PGRST202|schema cache|could not find the function|app_finance_v2_flags_v143/i.test(raw)){error.kombaxFinanceBackendMismatch=true;throw error}return false}}
async function dict(){const c=enc(cid());const [members,groups,disciplines,rules,targets,executions,yearRows]=await Promise.all([
backend.select('socios',`select=id,nombre,apellidos&club_id=eq.${c}&estado=eq.activo&order=apellidos.asc,nombre.asc&limit=1000`),backend.select('grupos',`select=id,nombre&club_id=eq.${c}&activo=eq.true&order=nombre.asc&limit=500`),backend.select('disciplinas',`select=id,nombre&club_id=eq.${c}&activa=eq.true&order=orden.asc,nombre.asc&limit=300`),backend.select('reglas_cobro',`select=*&club_id=eq.${c}&order=activa.desc,creado_en.desc&limit=500`).catch(()=>[]),backend.select('reglas_cobro_destinatarios',`select=*&club_id=eq.${c}&limit=1000`).catch(()=>[]),backend.select('reglas_cobro_ejecuciones',`select=*&club_id=eq.${c}&order=iniciado_en.desc&limit=100`).catch(()=>[]),backend.select('v_finanzas_metricas_anuales',`select=anio&club_id=eq.${c}&order=anio.desc&limit=30`).catch(()=>[])]);const years=[...new Set((yearRows||[]).map(x=>Number(x.anio)).filter(Boolean))];if(!years.length)years.push(new Date().getFullYear());return{members,groups,disciplines,rules,targets,executions,years}}
async function dash(){const n=v=>v||null;return backend.readRpc('app_finance_v2_dashboard_v150',{p_club_id:cid(),p_anio:filters.year?Number(filters.year):null,p_mes:filters.month?Number(filters.month):null,p_socio_id:n(filters.socio),p_grupo_id:n(filters.grupo),p_disciplina_id:n(filters.disciplina),p_categoria:n(filters.categoria),p_estado:n(filters.estado),p_regla_id:n(filters.regla),p_metodo:n(filters.metodo),p_antiguedad:n(filters.aging),p_limit:PAGE,p_offset:offset})}
const opts=(rows,lab,sel)=>rows.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(sel)?'selected':''}>${esc(lab(x))}</option>`).join('');
function filtersHtml(d){return `<div class="fv2-filters"><label>Año<select id="f-year">${d.years.map(y=>`<option value="${y}" ${String(y)===String(filters.year)?'selected':''}>${y}</option>`).join('')}</select></label><label>Mes<select id="f-month"><option value="">Todos</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(i+1)===filters.month?'selected':''}>${new Intl.DateTimeFormat('es-ES',{month:'long'}).format(new Date(2024,i,1))}</option>`).join('')}</select></label><label>Alumno<select id="f-socio"><option value="">Todos</option>${opts(d.members,x=>`${x.apellidos}, ${x.nombre}`,filters.socio)}</select></label><label>Grupo<select id="f-grupo"><option value="">Todos</option>${opts(d.groups,x=>x.nombre,filters.grupo)}</select></label><label>Disciplina<select id="f-disc"><option value="">Todas</option>${opts(d.disciplines,x=>x.nombre,filters.disciplina)}</select></label><label>Categoría<select id="f-cat"><option value="">Todas</option>${['cuota','matricula','licencia','material','competicion','evento','desplazamiento','otro'].map(x=>`<option value="${x}" ${x===filters.categoria?'selected':''}>${labelCat(x)}</option>`).join('')}</select></label><label>Estado<select id="f-state"><option value="">Todos</option>${['pendiente_abierto','vencido_abierto','cobrado','pendiente','parcialmente_pagada','pagada','anulada','exenta'].map(x=>`<option value="${x}" ${x===filters.estado?'selected':''}>${labelState(x)}</option>`).join('')}</select></label><label>Regla<select id="f-rule"><option value="">Todas</option>${opts(d.rules,x=>x.nombre,filters.regla)}</select></label><label>Método<select id="f-method"><option value="">Todos</option>${['transferencia','bizum','efectivo','tarjeta','otro'].map(x=>`<option value="${x}" ${x===filters.metodo?'selected':''}>${x}</option>`).join('')}</select></label><label>Antigüedad<select id="f-age"><option value="">Todas</option>${['sin_vencer','1_15','16_30','31_60','60_plus'].map(x=>`<option value="${x}" ${x===filters.aging?'selected':''}>${labelAge(x)}</option>`).join('')}</select></label><button class="btn btn-ghost" id="f-clear">Limpiar</button></div>`}
function kpis(s={},d={}){const debt=Number(s.alumnos_con_deuda||0);const items=[
  {label:'Generado',value:money(s.generado||0),note:'Cargos del periodo',kind:'clear'},
  {label:'Cobrado',value:money(s.cobrado||0),note:'Pagos validados',kind:'estado',filter:'cobrado'},
  {label:'Pendiente',value:money(s.pendiente||0),note:`${debt} alumno${debt===1?'':'s'} con deuda`,kind:'estado',filter:'pendiente_abierto'},
  {label:'Vencido',value:money(s.vencido||0),note:'Saldo fuera de plazo',kind:'estado',filter:'vencido_abierto'},
  {label:'Próx. 30 días',value:money(d.forecast_30d||0),note:'Saldo con vencimiento próximo',kind:'aging',filter:'sin_vencer'},
  {label:'Morosidad',value:`${Number(d.morosidad_pct||0).toFixed(1)} %`,note:'Vencido sobre saldo pendiente',kind:'estado',filter:'vencido_abierto'}
];return `<div class="fv2-kpis">${items.map(x=>`<button type="button" class="fv2-kpi ${x.filter&&((x.kind==='estado'&&filters.estado===x.filter)||(x.kind==='aging'&&filters.aging===x.filter))?'active':''}" data-kpi-kind="${x.kind}" data-kpi-filter="${esc(x.filter||'')}"><span>${x.label}</span><strong>${esc(x.value)}</strong><small>${esc(x.note)}</small></button>`).join('')}</div>`}

function filterContext(d){const chips=[];const lookup=(rows,id,lab=x=>x.nombre)=>rows.find(x=>String(x.id)===String(id))?.[lab instanceof Function?'__none__':'nombre'];
  if(filters.month)chips.push(new Intl.DateTimeFormat('es-ES',{month:'long'}).format(new Date(2024,Number(filters.month)-1,1)));
  if(filters.socio){const x=d.members.find(x=>String(x.id)===String(filters.socio));if(x)chips.push(`${x.nombre} ${x.apellidos}`)}
  if(filters.grupo){const x=d.groups.find(x=>String(x.id)===String(filters.grupo));if(x)chips.push(`Grupo · ${x.nombre}`)}
  if(filters.disciplina){const x=d.disciplines.find(x=>String(x.id)===String(filters.disciplina));if(x)chips.push(`Disciplina · ${x.nombre}`)}
  if(filters.categoria)chips.push(labelCat(filters.categoria));if(filters.estado)chips.push(labelState(filters.estado));if(filters.aging)chips.push(labelAge(filters.aging));if(filters.metodo)chips.push(filters.metodo);
  return `<div class="fv2-filterbar"><div><strong>Vista interactiva</strong><div class="fv2-filter-chips">${chips.length?chips.map(x=>`<span class="fv2-chip">${esc(x)}</span>`).join(''):'<span class="fv2-chip">Sin filtros adicionales</span>'}</div></div>${chips.length?'<button class="btn btn-ghost btn-sm" id="fv2-quick-clear">Restablecer vista</button>':''}</div>`}

function chart(ms=[]){if(!ms.length)return empty('Sin datos mensuales');const rows=[...ms].sort((a,b)=>String(a.mes).localeCompare(String(b.mes)));const W=Math.max(720,rows.length*82),H=250,left=58,right=18,top=20,bottom=40,plotW=W-left-right,plotH=H-top-bottom,max=Math.max(1,...rows.flatMap(x=>[+x.generado||0,+x.cobrado||0,+x.pendiente||0]));const xAt=i=>left+(rows.length===1?plotW/2:i*plotW/(rows.length-1));const yAt=v=>top+plotH-(Number(v||0)/max)*plotH;const label=x=>new Intl.DateTimeFormat('es-ES',{month:'short'}).format(new Date(`${String(x.mes).slice(0,7)}-01T12:00:00`)).replace('.','');const pts=key=>rows.map((r,i)=>`${xAt(i).toFixed(1)},${yAt(r[key]).toFixed(1)}`).join(' ');const area=()=>{if(!rows.length)return'';const first=xAt(0),last=xAt(rows.length-1),base=top+plotH;return `M ${first} ${base} L ${rows.map((r,i)=>`${xAt(i)} ${yAt(r.cobrado)}`).join(' L ')} L ${last} ${base} Z`};const tickVals=[0,max/2,max];const monthZones=rows.map((r,i)=>{const prev=i?xAt(i-1):left,next=i<rows.length-1?xAt(i+1):left+plotW,w=(next-prev)/2,start=Math.max(left,xAt(i)-w/2);return `<g class="fv2-month-hit" role="button" tabindex="0" data-chart-month="${Number(String(r.mes).slice(5,7))}"><rect x="${start.toFixed(1)}" y="${top}" width="${Math.max(35,w).toFixed(1)}" height="${plotH+26}" rx="8"></rect><text class="fv2-month-label" x="${xAt(i)}" y="${H-12}">${esc(label(r))}</text></g>`}).join('');const dots=(key,cls,state)=>rows.map((r,i)=>{const title=`${key==='generado'?'Generado':key==='cobrado'?'Cobrado':'Pendiente'} · ${label(r)} · ${money(r[key]||0)}`;return `<circle class="fv2-chart-dot ${cls}" tabindex="0" role="button" data-chart-point="1" data-month="${Number(String(r.mes).slice(5,7))}" data-state="${state}" cx="${xAt(i)}" cy="${yAt(r[key])}" r="4"><title>${esc(title)}</title></circle>`}).join('');return `<div class="fv2-chart-wrap"><svg class="fv2-chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución financiera mensual">${tickVals.map(v=>`<line class="fv2-gridline" x1="${left}" x2="${W-right}" y1="${yAt(v)}" y2="${yAt(v)}"></line><text class="fv2-axis-label" x="4" y="${yAt(v)+3}">${esc(money(v))}</text>`).join('')}${monthZones}<path class="fv2-area-collected" d="${area()}"></path><polyline class="fv2-series-generated" points="${pts('generado')}"></polyline><polyline class="fv2-series-collected" points="${pts('cobrado')}"></polyline><polyline class="fv2-series-pending" points="${pts('pendiente')}"></polyline>${dots('generado','generated','')}${dots('cobrado','collected','cobrado')}${dots('pendiente','pending','pendiente_abierto')}</svg></div><div class="fv2-legend"><button type="button" data-series-state="" class="${!filters.estado?'active':''}"><i class="g"></i>Generado</button><button type="button" data-series-state="cobrado" class="${filters.estado==='cobrado'?'active':''}"><i class="c"></i>Cobrado</button><button type="button" data-series-state="pendiente_abierto" class="${filters.estado==='pendiente_abierto'?'active':''}"><i class="p"></i>Pendiente</button></div>`}

function histogram(ms=[]){if(!ms.length)return empty('Sin datos mensuales');const rows=[...ms].sort((a,b)=>String(a.mes).localeCompare(String(b.mes))).slice(-12);const W=Math.max(760,rows.length*88),H=270,left=58,right=18,top=22,bottom=42,plotW=W-left-right,plotH=H-top-bottom,max=Math.max(1,...rows.flatMap(x=>[+x.generado||0,+x.cobrado||0,+x.pendiente||0]));const slot=plotW/Math.max(1,rows.length),barW=Math.max(9,Math.min(18,(slot-16)/3)),gap=4;const y=v=>top+plotH-(Number(v||0)/max)*plotH;const label=x=>new Intl.DateTimeFormat('es-ES',{month:'short'}).format(new Date(`${String(x.mes).slice(0,7)}-01T12:00:00`)).replace('.','');const specs=[['generado','generated',''],['cobrado','collected','cobrado'],['pendiente','pending','pendiente_abierto']];const ticks=[0,max/2,max];const groups=rows.map((r,i)=>{const gx=left+i*slot+(slot-(barW*3+gap*2))/2;const bars=specs.map(([key,cls,state],j)=>{const v=Number(r[key]||0),yy=y(v),hh=Math.max(1,top+plotH-yy),x=gx+j*(barW+gap),title=`${key==='generado'?'Generado':key==='cobrado'?'Cobrado':key==='pendiente'?'Pendiente':'Vencido'} · ${label(r)} · ${money(v)}`;const month=String(Number(String(r.mes).slice(5,7))),active=String(filters.month||'')===month&&String(filters.estado||'')===String(state||'');return `<rect class="fv2-hist-bar fv2-hist-${cls} ${active?'active':''}" tabindex="0" role="button" aria-pressed="${active?'true':'false'}" data-hist-month="${month}" data-hist-state="${state}" style="--fv2-delay:${Math.min(520,i*34+j*18)}ms" x="${x.toFixed(1)}" y="${yy.toFixed(1)}" width="${barW.toFixed(1)}" height="${hh.toFixed(1)}" rx="3"><title>${esc(title)}</title></rect>`}).join('');return `${bars}<text class="fv2-month-label" x="${(left+i*slot+slot/2).toFixed(1)}" y="${H-13}">${esc(label(r))}</text>`}).join('');return `<div class="fv2-chart-wrap"><svg class="fv2-hist-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Histograma financiero mensual">${ticks.map(v=>`<line class="fv2-gridline" x1="${left}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}"></line><text class="fv2-axis-label" x="4" y="${y(v)+3}">${esc(money(v))}</text>`).join('')}${groups}</svg></div><div class="fv2-legend"><button type="button" data-series-state="" class="${!filters.estado?'active':''}"><i class="g"></i>Generado</button><button type="button" data-series-state="cobrado" class="${filters.estado==='cobrado'?'active':''}"><i class="c"></i>Cobrado</button><button type="button" data-series-state="pendiente_abierto" class="${filters.estado==='pendiente_abierto'?'active':''}"><i class="p"></i>Pendiente</button></div>`}

function aging(a=[]){const keys=['sin_vencer','1_15','16_30','31_60','60_plus'],m=new Map(a.map(x=>[x.bucket,x])),total=keys.reduce((n,k)=>n+Number(m.get(k)?.total||0),0);let offset=0;const circles=keys.map((k,i)=>{const value=Number(m.get(k)?.total||0),pct=total>0?value/total*100:0,active=filters.aging===k,el=`<circle class="fv2-donut-seg a${i} ${active?'active':''}" role="button" tabindex="0" aria-pressed="${active?'true':'false'}" data-aging="${k}" style="--fv2-offset:${(-offset).toFixed(3)};--fv2-delay:${i*90}ms" cx="80" cy="80" r="56" pathLength="100" stroke-dasharray="${pct.toFixed(3)} ${(100-pct).toFixed(3)}" stroke-dashoffset="${(-offset).toFixed(3)}" transform="rotate(-90 80 80)"><title>${esc(labelAge(k))}: ${esc(money(value))}</title></circle>`;offset+=pct;return el}).join('');const list=keys.map((k,i)=>{const x=m.get(k)||{},value=Number(x.total||0),pct=total>0?value/total*100:0;return `<button type="button" data-aging="${k}" class="${filters.aging===k?'active':''}"><span>${labelAge(k)}</span><strong>${money(value)}</strong><small>${Number(x.cargos||0)} cargos · ${pct.toFixed(1)} %</small></button>`}).join('');return `<div class="fv2-donut-layout"><svg class="fv2-donut" viewBox="0 0 160 160" role="img" aria-label="Distribución de deuda por antigüedad"><circle class="fv2-donut-bg" cx="80" cy="80" r="56"></circle>${circles}<text class="fv2-donut-total" x="80" y="76">${esc(money(total))}</text><text class="fv2-donut-sub" x="80" y="92">saldo pendiente</text></svg><div class="fv2-aging-list">${list}</div></div>`}

function categoryBreakdown(rows=[]){if(!rows.length)return empty('Sin distribución por categoría');const max=Math.max(1,...rows.map(x=>Number(x.generado||0)));return `<div class="fv2-hbars">${rows.slice(0,8).map((x,i)=>`<button type="button" class="fv2-hbar ${filters.categoria===x.categoria?'active':''}" data-category="${esc(x.categoria)}"><span class="fv2-hbar-label"><strong>${esc(labelCat(x.categoria))}</strong><small>${Number(x.cargos||0)} cargos · ${Number(x.alumnos||0)} alumnos</small></span><span class="fv2-hbar-track"><i class="fv2-hbar-fill" style="width:${Math.max(2,Number(x.generado||0)/max*100).toFixed(2)}%;--fv2-delay:${i*55}ms"></i></span><span class="fv2-hbar-value">${esc(money(x.generado||0))}</span></button>`).join('')}</div>`}

function dimensionBreakdown(d){const rows=breakdownMode==='disciplines'?(d.disciplines||[]): (d.groups||[]),kind=breakdownMode==='disciplines'?'disciplina':'grupo';if(!rows.length)return empty(`Sin datos por ${kind}`);const max=Math.max(1,...rows.map(x=>Number(x.generado||0)));return `<div class="fv2-split-tabs"><button type="button" data-breakdown-mode="groups" class="${breakdownMode==='groups'?'active':''}">Por grupo</button><button type="button" data-breakdown-mode="disciplines" class="${breakdownMode==='disciplines'?'active':''}">Por disciplina</button></div><div class="fv2-hbars" style="margin-top:10px">${rows.slice(0,8).map((x,i)=>`<button type="button" class="fv2-hbar ${(kind==='grupo'&&filters.grupo===String(x.id))||(kind==='disciplina'&&filters.disciplina===String(x.id))?'active':''}" data-dimension="${kind}" data-dimension-id="${esc(x.id)}"><span class="fv2-hbar-label"><strong>${esc(x.nombre)}</strong><small>${Number(x.alumnos||0)} alumnos · ${Number(x.cargos||0)} cargos</small></span><span class="fv2-hbar-track"><i class="fv2-hbar-fill" style="width:${Math.max(2,Number(x.generado||0)/max*100).toFixed(2)}%;--fv2-delay:${i*55}ms"></i></span><span class="fv2-hbar-value">${esc(money(x.generado||0))}</span></button>`).join('')}</div><div class="fv2-attribution">${esc(d.attribution_note||'')}</div>`}
function charges(rows=[]){if(!rows.length)return empty('Sin cargos para estos filtros');const rs=rows.map(r=>`<tr class="fv2-row" data-charge="${esc(r.cuota_id)}"><td><strong>${esc(`${r.socio_apellidos||''}, ${r.socio_nombre||''}`)}</strong><br><small>${esc(r.grupos||'')}</small></td><td>${esc(r.concepto||'—')}<br><small>${labelCat(r.categoria)}</small></td><td>${esc(String(r.periodo||'').slice(0,7))}</td><td>${money(r.importe)}</td><td>${money(r.pagado_validado)}</td><td><strong>${money(r.saldo)}</strong></td><td>${dateFmt(r.vencimiento)}</td><td>${badge(labelState(r.estado),Number(r.saldo||0)<=0?'ok':Number(r.dias_vencido||0)>0?'danger':'warn')}</td><td>${esc(r.regla_nombre||'Manual')}</td><td>${esc(r.recibo_numero||'—')}</td></tr>`);const mobile=rows.map(r=>`<button class="fv2-card fv2-row" data-charge="${esc(r.cuota_id)}"><div class="r"><div><strong>${esc(`${r.socio_nombre||''} ${r.socio_apellidos||''}`)}</strong><small>${esc(r.concepto||'')}</small></div><strong>${money(r.saldo)}</strong></div><div class="r"><small>${labelState(r.estado)}</small><small>Vence ${dateFmt(r.vencimiento)}</small></div></button>`).join('');return `<div class="fv2-desktop">${table(['Alumno','Concepto','Periodo','Importe','Pagado','Pendiente','Vence','Estado','Regla','Recibo'],rs)}</div><div class="fv2-mobile">${mobile}</div>`}
function tabs(){return `<div class="fv2-tabs">${[['summary','Resumen'],['charges','Cargos'],['automations','Automatizaciones'],['payments','Pagos'],['receipts','Recibos'],['reports','Informes']].map(([id,l])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${l}</button>`).join('')}</div>`}
function pagination(d){if(Number(d.total_rows||0)<=PAGE)return'';return `<div class="fv2-actions" style="justify-content:flex-end;margin-top:10px"><button class="btn btn-ghost btn-sm" id="prev" ${offset<=0?'disabled':''}>Anterior</button><button class="btn btn-ghost btn-sm" id="next" ${offset+PAGE>=Number(d.total_rows||0)?'disabled':''}>Siguiente</button></div>`}
function detail(r,reportsEnabled=false){const actions=[has(state.session,'paymentAdmin')&&Number(r.saldo||0)>0?'<button class="btn btn-primary" id="detail-pay">Registrar cobro</button>':'',reportsEnabled?'<button class="btn btn-ghost" id="detail-account">Estado de cuenta PDF</button>':''].filter(Boolean).join('');openDetail({title:`${r.socio_nombre||''} ${r.socio_apellidos||''}`.trim(),subtitle:r.concepto||'Cargo',body:`<p><strong>Importe:</strong> ${money(r.importe)}</p><p><strong>Pagado:</strong> ${money(r.pagado_validado)}</p><p><strong>Pendiente:</strong> ${money(r.saldo)}</p><p><strong>Vencimiento:</strong> ${dateFmt(r.vencimiento)}</p><p><strong>Grupo:</strong> ${esc(r.grupos||'—')}</p><p><strong>Disciplina:</strong> ${esc(r.disciplinas||'—')}</p><p><strong>Regla:</strong> ${esc(r.regla_nombre||'Manual')}</p><p><strong>Recibo:</strong> ${esc(r.recibo_numero||'—')}</p>`,actions});document.getElementById('detail-pay')?.addEventListener('click',()=>{closeModal();openForm({title:'Registrar cobro',fields:[{name:'importe',label:'Importe',type:'number',step:'0.01',min:.01,required:true,value:r.saldo},{name:'fecha',label:'Fecha',type:'date',required:true,value:isoDate()},{name:'metodo',label:'Método',type:'select',options:['transferencia','bizum','efectivo','tarjeta','otro'].map(x=>({value:x,label:x}))},{name:'referencia',label:'Referencia'},{name:'observaciones',label:'Observaciones',type:'textarea',full:true}],onSubmit:async v=>{await repos.finance.adminPayment({...v,cuota_id:r.cuota_id});toast('Cobro registrado');await renderFinancePremium()}})});document.getElementById('detail-account')?.addEventListener('click',async()=>{closeModal();await generateReport('estado_cuenta',{socio:r.socio_id})})}
function recipients(d){return d.scopeType==='todos_activos'?[{tipo:'todos_activos'}]:(d.scopeIds||[]).map(id=>({tipo:d.scopeType,id}))}
function wizard(D){const d={categoria:'cuota',concepto:'',scopeType:'socio',scopeIds:[],importe:'',periodo:monthStart(),vencimiento:nextDue(),observaciones:'',preview:null};let step=0;const names=['Categoría','Concepto','Destinatarios','Importe','Periodo','Vencimiento','Observaciones','Preview'];const {wrap}=openDetail({title:'+ Nuevo cargo',subtitle:'8 pasos · preview obligatorio',body:'<div id="wiz"></div>',actions:'<button class="btn btn-ghost" id="back">Atrás</button><button class="btn btn-primary" id="go">Siguiente</button>'});const body=wrap.querySelector('#wiz'),back=wrap.querySelector('#back'),go=wrap.querySelector('#go');function save(){const x=body.querySelector('[data-in]');if(step===0)d.categoria=x.value;if(step===1)d.concepto=x.value.trim();if(step===2){d.scopeType=body.querySelector('#stype').value;d.scopeIds=[...body.querySelector('#sids').selectedOptions].map(o=>o.value)}if(step===3)d.importe=x.value;if(step===4)d.periodo=x.value;if(step===5)d.vencimiento=x.value;if(step===6)d.observaciones=x.value.trim()}function rows(){return d.scopeType==='grupo'?D.groups:d.scopeType==='disciplina'?D.disciplines:D.members}function lab(x){return d.scopeType==='socio'?`${x.apellidos}, ${x.nombre}`:x.nombre}async function prev(){d.preview=await backend.readRpc('app_finance_v2_preview_cargo_v144',{p_club_id:cid(),p_destinatarios:recipients(d),p_categoria:d.categoria,p_concepto:d.concepto,p_importe:Number(d.importe),p_periodo:d.periodo,p_vencimiento:d.vencimiento})}async function draw(){back.disabled=step===0;go.textContent=step===7?'Crear cargos':'Siguiente';let input='';if(step===0)input=`<select data-in>${['cuota','matricula','licencia','material','competicion','evento','desplazamiento','otro'].map(x=>`<option value="${x}" ${x===d.categoria?'selected':''}>${labelCat(x)}</option>`).join('')}</select>`;if(step===1)input=`<input data-in value="${esc(d.concepto)}" placeholder="Concepto">`;if(step===2)input=`<select id="stype"><option value="socio">Alumno(s)</option><option value="grupo" ${d.scopeType==='grupo'?'selected':''}>Grupo</option><option value="disciplina" ${d.scopeType==='disciplina'?'selected':''}>Disciplina</option><option value="todos_activos" ${d.scopeType==='todos_activos'?'selected':''}>Todos activos</option></select><select id="sids" data-in multiple ${d.scopeType==='todos_activos'?'disabled':''}>${rows().map(x=>`<option value="${esc(x.id)}" ${d.scopeIds.includes(x.id)?'selected':''}>${esc(lab(x))}</option>`).join('')}</select>`;if(step===3)input=`<input data-in type="number" min="0" step="0.01" value="${esc(d.importe)}">`;if(step===4)input=`<input data-in type="date" value="${d.periodo}">`;if(step===5)input=`<input data-in type="date" value="${d.vencimiento}">`;if(step===6)input=`<textarea data-in>${esc(d.observaciones)}</textarea>`;if(step===7){if(!d.preview)await prev();input=`<p><strong>Se crearán ${d.preview.cargos||0} cargos · ${money(d.preview.total||0)}</strong></p><div class="fv2-preview">${(d.preview.destinatarios||[]).slice(0,100).map(x=>`<div><span>${esc(x.nombre||x.socio_id)}</span><strong>${money(x.importe)}</strong></div>`).join('')}</div>`}body.innerHTML=`<div class="fv2-wsteps">${names.map((_,i)=>`<i class="${i<=step?'on':''}"></i>`).join('')}</div><div class="fv2-step"><small>Paso ${step+1} de 8</small><h3>${names[step]}</h3>${input}</div>`;body.querySelector('#stype')?.addEventListener('change',e=>{d.scopeType=e.target.value;d.scopeIds=[];draw()})}back.addEventListener('click',async()=>{save();d.preview=null;if(step)step--;await draw()});go.addEventListener('click',async()=>{try{save();if(step===1&&!d.concepto)throw Error('Indica el concepto.');if(step===2&&d.scopeType!=='todos_activos'&&!d.scopeIds.length)throw Error('Selecciona destinatarios.');if(step===3&&(!d.importe||Number(d.importe)<0))throw Error('Indica un importe válido.');if(step<7){step++;if(step===7)await prev();await draw();return}if(!d.preview?.cargos)throw Error('El preview no contiene destinatarios.');go.disabled=true;const out=await backend.mutate('finance.cargo.crear',{categoria:d.categoria,concepto:d.concepto,importe:Number(d.importe),periodo:d.periodo,vencimiento:d.vencimiento,observaciones:d.observaciones||null,destinatarios:recipients(d)});toast(`Cargos creados: ${out?.cargos_creados??d.preview.cargos}`);closeModal();offset=0;await renderFinancePremium()}catch(e){setError(e);go.disabled=false}});draw().catch(setError)}
function newRule(D){const scopes=[{value:'todos_activos',label:'Todos los alumnos activos'},...D.groups.map(x=>({value:`grupo:${x.id}`,label:`Grupo · ${x.nombre}`})),...D.disciplines.map(x=>({value:`disciplina:${x.id}`,label:`Disciplina · ${x.nombre}`})),...D.members.map(x=>({value:`socio:${x.id}`,label:`Alumno · ${x.apellidos}, ${x.nombre}`}))];openForm({title:'Nueva automatización',subtitle:'La regla puede guardarse en pausa. Las recurrencias reales además requieren el flag del club.',fields:[{name:'nombre',label:'Nombre',required:true},{name:'categoria',label:'Categoría',type:'select',options:['cuota','matricula','licencia','material','competicion','evento','desplazamiento','otro'].map(x=>({value:x,label:labelCat(x)}))},{name:'concepto',label:'Concepto',required:true},{name:'importe',label:'Importe',type:'number',step:'0.01',min:0,required:true},{name:'periodicidad',label:'Periodicidad',type:'select',options:['mensual','trimestral','semestral','anual','unica'].map(x=>({value:x,label:x}))},{name:'fecha_inicio',label:'Inicio',type:'date',value:monthStart(),required:true},{name:'dia_generacion',label:'Día generación',type:'number',min:1,max:28,value:1},{name:'dia_vencimiento',label:'Día vencimiento',type:'number',min:1,max:28,value:10},{name:'scope',label:'Destinatarios',type:'select',options:scopes,required:true},{name:'activa',label:'Activar esta regla',type:'checkbox',value:false,full:true}],onSubmit:async v=>{const r=await backend.mutate('finance.regla.guardar',{nombre:v.nombre,categoria:v.categoria,concepto:v.concepto,importe:+v.importe,periodicidad:v.periodicidad,fecha_inicio:v.fecha_inicio,dia_generacion:+v.dia_generacion,dia_vencimiento:+v.dia_vencimiento,zona_horaria:'Europe/Madrid',activa:v.activa===true});const [tipo,id]=String(v.scope).split(':');await backend.mutate('finance.destinatario.añadir',{regla_id:r.regla_id,tipo,socio_id:tipo==='socio'?id:null,grupo_id:tipo==='grupo'?id:null,disciplina_id:tipo==='disciplina'?id:null});toast(v.activa?'Automatización activa':'Automatización guardada en pausa');tab='automations';await renderFinancePremium()}})}
async function toggleRule(rule){try{await backend.mutate('finance.regla.guardar',{id:rule.id,activa:!rule.activa});toast(rule.activa?'Automatización pausada':'Automatización activada');await renderFinancePremium()}catch(e){setError(e)}}
async function simulate(id){try{const x=await backend.readRpc('app_finance_v2_preview_regla_v143',{p_regla_id:id,p_fecha:isoDate(),p_forzar_ciclo_actual:false});openDetail({title:'Simulación shadow',body:`<p><strong>${x.cargos||0} cargos · ${money(x.total||0)}</strong></p><p>${x.corresponde===false?esc(x.motivo||'Hoy no corresponde generar'):'No se insertará ningún cargo en esta simulación.'}</p>`})}catch(e){setError(e)}}
function automation(D){const r=D.rules.map(x=>`<tr><td><strong>${esc(x.nombre)}</strong><br><small>${esc(x.concepto)}</small></td><td>${labelCat(x.categoria)}</td><td>${money(x.importe)}</td><td>${esc(x.periodicidad)}</td><td>Día ${x.dia_generacion} / vence ${x.dia_vencimiento}</td><td>${badge(x.activa?'Activa':'En pausa',x.activa?'ok':'neutral')}</td><td><div class="row-actions"><button class="btn btn-ghost btn-sm sim" data-id="${x.id}">Simular</button><button class="btn btn-ghost btn-sm toggle-rule" data-id="${x.id}">${x.activa?'Pausar':'Activar'}</button></div></td></tr>`);const ex=D.executions.map(x=>`<tr><td>${dateFmt(x.fecha_proceso)}</td><td>${esc(x.modo||'—')}</td><td>${badge(x.estado,x.estado==='completada'?'ok':x.estado==='error'?'danger':'warn')}</td><td>${x.shadow?'Sí':'No'}</td><td>${x.estadisticas?.cargos_creados??x.estadisticas?.cargos_simulados??0}</td></tr>`);return `${card('Reglas',r.length?table(['Regla','Categoría','Importe','Periodicidad','Calendario','Estado','Acción'],r):empty('Sin automatizaciones'))}${card('Ejecuciones',ex.length?table(['Fecha','Modo','Estado','Shadow','Cargos'],ex):empty('Sin ejecuciones'))}`}
function qaPanel(Q,P){if(!Q)return `<div class="fv2-qa"><strong>QA financiero 20082 no disponible</strong><p class="muted">La interfaz Premium seguirá funcionando, pero no se puede aprobar la recurrencia real hasta instalar la capa QA.</p></div>`;const a=Q.anomalies||{},b=a.blocking||{},w=a.warnings||{},f=Q.flags||{},runs=Q.recent_shadow_runs||[];const approved=Q.approved===true;const last=runs[0];const prev=runs[1];const equivalent=Boolean(last&&prev&&last.estado==='ok'&&prev.estado==='ok'&&last.fecha_proceso===prev.fecha_proceso&&last.fingerprint===prev.fingerprint);const finalReady=P?.ready===true,live=P?.live===true;const runRows=runs.map(x=>`<tr><td>${dateFmt(x.fecha_proceso)}</td><td>${badge(x.estado,x.estado==='ok'?'ok':x.estado==='blocked'||x.estado==='error'?'danger':'warn')}</td><td>${x.reglas||0}</td><td>${x.cargos_simulados||0}</td><td>${money(x.importe_total||0)}</td><td><span class="fv2-report-id">${esc(String(x.fingerprint||'').slice(0,12))}</span></td><td>${dateFmt(x.creado_en)}</td></tr>`);return `<section class="fv2-qa"><div class="fv2-qa-head"><div><div class="page-kicker">QA 20083 · FINAL PILOT GATE</div><h3>${live?'Piloto recurrente activo':finalReady?'Listo para activación controlada':approved?'QA aprobado · gate final cerrado':'Recurrencia real bloqueada'}</h3><p class="muted">20.083 añade un segundo cierre independiente: aunque QA y recurring estén activos, no se genera ningún cargo recurrente real hasta abrir expresamente <code>finance_pilot_live_enabled</code>.</p></div>${badge(live?'LIVE':finalReady?'READY':'CLOSED',live?'danger':finalReady?'ok':'warn')}</div><div class="fv2-qa-grid"><div class="fv2-qa-cell"><span>Anomalías bloqueantes</span><strong class="${Number(b.total||0)===0?'fv2-qa-ok':'fv2-qa-block'}">${Number(b.total||0)}</strong><small>Duplicados, saldo/recibo, informes</small></div><div class="fv2-qa-cell"><span>Reglas activas</span><strong>${Number(P?.active_rules??w.active_rules??0)}</strong><small>Sin destinatario: ${Number(w.active_rules_without_target||0)}</small></div><div class="fv2-qa-cell"><span>Pagos por validar</span><strong class="${Number(w.payments_pending_validation||0)>0?'fv2-qa-warn':''}">${Number(w.payments_pending_validation||0)}</strong><small>No cuentan como cobrados</small></div><div class="fv2-qa-cell"><span>Dos Shadow equivalentes</span><strong class="${equivalent?'fv2-qa-ok':'fv2-qa-warn'}">${equivalent?'Sí':'No'}</strong><small>Última huella: ${esc(String(last?.fingerprint||'—').slice(0,10))}</small></div></div><div class="fv2-qa-actions"><button class="btn btn-primary" id="qa-shadow-run">Ejecutar Shadow QA</button>${direction()&&!approved?'<button class="btn btn-ghost" id="qa-approve">Aprobar Shadow QA</button>':''}${direction()&&approved?'<button class="btn btn-ghost" id="qa-revoke">Revocar aprobación</button>':''}<span class="muted">Recurring: ${f.finance_recurring_enabled?'ON':'OFF'} · QA: ${approved?'OPEN':'CLOSED'} · Pilot live: ${live?'OPEN':'CLOSED'}</span></div>${finalReady&&!live?`<div class="alert alert-info" style="margin-top:12px"><strong>Listo para piloto</strong><span>El backend está preparado, pero 20.083 no abre el gate final automáticamente. La activación requiere la frase exacta <b>ACTIVAR RECURRENCIA</b> mediante la operación auditada <code>finance.pilot.activar</code>.</span></div>`:''}${runRows.length?`<div style="margin-top:12px">${table(['Fecha proceso','Estado','Reglas','Simulados','Total','Huella','Ejecutado'],runRows)}</div>`:''}</section>`}
async function runQaShadow(){try{const out=await backend.mutate('finance.qa.shadow.run',{fecha:isoDate()});openDetail({title:'Shadow QA completado',subtitle:'No se ha creado ningún cargo real.',body:`<p><strong>Estado:</strong> ${esc(out.estado||'—')}</p><p><strong>Cargos simulados:</strong> ${esc(out.resultado?.cargos_simulados||0)}</p><p><strong>Total:</strong> ${money(out.resultado?.importe_total||0)}</p><p><strong>Huella:</strong> <span class="fv2-report-id">${esc(out.fingerprint||'—')}</span></p>`});await renderFinancePremium()}catch(e){setError(e)}}
async function approveQa(){try{await backend.mutate('finance.qa.aprobar',{});toast('Shadow QA aprobado. La recurrencia real sigue dependiendo del flag del club.');await renderFinancePremium()}catch(e){setError(e)}}
async function revokeQa(){try{await backend.mutate('finance.qa.revocar',{motivo:'Revocación manual desde Finanzas Premium'});toast('Aprobación QA revocada');await renderFinancePremium()}catch(e){setError(e)}}
function payments(rows,members){const m=new Map(members.map(x=>[x.id,x]));const ordered=[...rows].sort((a,b)=>(a.estado_validacion==='pendiente'?0:1)-(b.estado_validacion==='pendiente'?0:1)||String(b.fecha||'').localeCompare(String(a.fecha||'')));const r=ordered.map(p=>{const s=m.get(p.socio_id);return `<tr><td>${dateFmt(p.fecha)}</td><td>${esc(s?`${s.apellidos}, ${s.nombre}`:'—')}</td><td>${money(p.importe)}</td><td>${esc(p.metodo||'—')}</td><td>${badge(p.estado_validacion,p.estado_validacion==='validado'?'ok':p.estado_validacion==='rechazado'?'danger':'warn')}</td><td>${p.estado_validacion==='pendiente'&&has(state.session,'paymentAdmin')?`<button class="btn btn-primary btn-sm val" data-id="${p.id}">Validar</button> <button class="btn btn-ghost btn-sm rej" data-id="${p.id}">Rechazar</button>`:''}</td></tr>`});return card('Pagos',r.length?table(['Fecha','Alumno','Importe','Método','Estado','Acciones'],r):empty('Sin pagos'))}
function receipts(rows){const r=rows.map(x=>`<tr><td><strong>${esc(x.numero||'—')}</strong></td><td>${esc(x.socio_nombre||'—')}</td><td>${esc(x.concepto||x.actividad||'—')}</td><td>${dateFmt(x.fecha_pago)}</td><td>${money(x.importe)}</td><td>${badge(x.anulado_en?'Anulado':'Cobrado',x.anulado_en?'danger':'ok')}</td><td><div class="fv2-receipt-actions"><button type="button" class="btn btn-primary btn-sm fv2-view-receipt" data-receipt-id="${esc(x.id)}">Ver recibo</button></div></td></tr>`);return card('Recibos',r.length?table(['Número','Alumno','Concepto','Fecha','Importe','Estado','Documento'],r):empty('Sin recibos'))}
function csv(rows){const h=['Alumno','Concepto','Categoria','Periodo','Importe','Pagado','Pendiente','Vencimiento','Estado','Grupo','Disciplina','Regla','Recibo'];const data=[h,...rows.map(r=>[`${r.socio_nombre||''} ${r.socio_apellidos||''}`.trim(),r.concepto,r.categoria,r.periodo,r.importe,r.pagado_validado,r.saldo,r.vencimiento,r.estado,r.grupos,r.disciplinas,r.regla_nombre,r.recibo_numero])].map(a=>a.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const b=new Blob(['\ufeff'+data],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`kombax-finanzas-${filters.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

const currentReportFilters=()=>({...filters});
async function reportList(){return backend.readRpc('app_finance_v2_reports_v145',{p_club_id:cid(),p_limit:150}).catch(()=>[])}
async function ensureReportPdf(reportId){return backend.invokeFunction('finance-report',{report_id:reportId})}
async function generateReport(tipo='vista_actual',{socio='',source_report_id='',titulo='',overrides={}}={}){
  try{
    const filtros={...currentReportFilters(),...overrides};if(socio)filtros.socio=socio;
    const created=await backend.mutate('finance.informe.crear',{tipo,titulo,filtros,source_report_id:source_report_id||null});
    let pdfReady=true;
    try{await ensureReportPdf(created.report_id)}catch(error){pdfReady=false;console.warn('Snapshot creado; PDF pendiente de regeneración:',error)}
    toast(pdfReady?`Informe ${created.identificador} generado`:`Snapshot ${created.identificador} guardado; PDF pendiente`);
    tab='reports';await renderFinancePremium();return created;
  }catch(e){setError(e);throw e}
}
async function openReportPdf(report){
  try{
    let payload=await backend.readRpc('app_finance_v2_report_payload_v145',{p_report_id:report.id});
    if(!payload?.archivo_path){await ensureReportPdf(report.id);payload=await backend.readRpc('app_finance_v2_report_payload_v145',{p_report_id:report.id})}
    if(!payload?.archivo_path)throw new Error('El PDF todavía no está disponible.');
    const url=await backend.signedUrl('finance-reports',payload.archivo_path,600);
    window.open(url,'_blank','noopener,noreferrer');
  }catch(e){setError(e)}
}
function reportHistory(rows=[]){
  const rs=rows.map(r=>`<tr><td><span class="fv2-report-id">${esc(r.identificador)}</span><br><small>v${esc(r.version)}</small></td><td><strong>${esc(r.titulo)}</strong><br><small>${esc(labelReportType(r.tipo))}</small></td><td>${dateFmt(r.generado_en)}</td><td>${esc(r.dataset_rows)}</td><td>${money(r.totales?.generado||0)}</td><td>${money(r.totales?.pendiente||0)}</td><td>${r.archivo_path?'<span class="fv2-report-ready">PDF listo</span>':'<span class="fv2-report-pending">PDF pendiente</span>'}</td><td><div class="row-actions"><button class="btn btn-primary btn-sm report-open" data-id="${esc(r.id)}">${r.archivo_path?'Ver PDF':'Generar PDF'}</button><button class="btn btn-ghost btn-sm report-refresh" data-id="${esc(r.id)}">Versión actualizada</button></div></td></tr>`);
  return rs.length?table(['Identificador','Informe','Generado','Filas','Generado','Pendiente','Archivo','Acciones'],rs):empty('Aún no hay informes históricos','Cuando generes un informe, su snapshot quedará guardado aquí.');
}
function reportsPanel(F,H,R){
  if(!F.finance_reports_enabled)return card('Informes Premium',`<div class="fv2-report-note"><strong>Informes todavía desactivados para este club</strong><span>Activa <code>finance_reports_enabled</code> únicamente durante el rollout controlado. Finanzas RC13 y el dashboard Premium siguen funcionando sin esta capa.</span></div>`);
  return `${card('Generar informe',`<div class="fv2-report-note"><strong>Snapshot histórico inmutable</strong><span>El informe conserva filtros, totales, dataset, branding y actor del momento de generación. Los cambios posteriores no modifican el documento.</span></div><div class="fv2-report-actions"><button class="btn btn-primary" id="report-current">Generar informe de esta vista</button><button class="btn btn-ghost" id="report-new">Elegir tipo de informe</button>${filters.socio?'<button class="btn btn-ghost" id="report-account-current">Estado de cuenta del alumno filtrado</button>':''}<button class="btn btn-ghost" id="export">Exportar CSV</button></div>`)}${card('Histórico de informes',reportHistory(H))}`;
}
function openReportWizard(R){
  openForm({title:'Nuevo informe financiero',subtitle:'Se generará desde los datos consolidados y quedará congelado como snapshot histórico.',fields:[
    {name:'tipo',label:'Tipo de informe',type:'select',required:true,value:'tesoreria_mensual',options:REPORT_TYPES.filter(([id])=>id!=='vista_actual').map(([value,label])=>({value,label}))},
    {name:'socio',label:'Alumno',type:'select',options:[{value:'',label:'Usar filtro actual / no aplica'},...R.members.map(x=>({value:x.id,label:`${x.apellidos}, ${x.nombre}`}))]},
    {name:'grupo',label:'Grupo',type:'select',options:[{value:'',label:'Usar filtro actual / no aplica'},...R.groups.map(x=>({value:x.id,label:x.nombre}))]},
    {name:'disciplina',label:'Disciplina',type:'select',options:[{value:'',label:'Usar filtro actual / no aplica'},...R.disciplines.map(x=>({value:x.id,label:x.nombre}))]},
    {name:'categoria',label:'Categoría',type:'select',options:[{value:'',label:'Usar filtro actual / no aplica'},...['cuota','matricula','licencia','material','competicion','evento','desplazamiento','otro'].map(x=>({value:x,label:labelCat(x)}))]},
    {name:'metodo',label:'Método de pago',type:'select',options:[{value:'',label:'Usar filtro actual / no aplica'},...['transferencia','bizum','efectivo','tarjeta','otro'].map(x=>({value:x,label:x}))]},
    {name:'titulo',label:'Título opcional',full:true}
  ],submitText:'Crear snapshot y PDF',onSubmit:async v=>{const selected={socio:v.socio||filters.socio,grupo:v.grupo||filters.grupo,disciplina:v.disciplina||filters.disciplina,categoria:v.categoria||filters.categoria,metodo:v.metodo||filters.metodo};if(v.tipo==='estado_cuenta'&&!selected.socio)throw new Error('Selecciona un alumno para el estado de cuenta.');if(v.tipo==='por_grupo'&&!selected.grupo)throw new Error('Selecciona un grupo.');if(v.tipo==='por_disciplina'&&!selected.disciplina)throw new Error('Selecciona una disciplina.');if(v.tipo==='por_categoria'&&!selected.categoria)throw new Error('Selecciona una categoría.');if(v.tipo==='por_metodo_pago'&&!selected.metodo)throw new Error('Selecciona un método de pago.');await generateReport(v.tipo,{socio:selected.socio,titulo:v.titulo,overrides:{grupo:selected.grupo,disciplina:selected.disciplina,categoria:selected.categoria,metodo:selected.metodo}})}})
}

function resetFinanceFilters(){Object.assign(filters,{year:String(new Date().getFullYear()),month:'',socio:'',grupo:'',disciplina:'',categoria:'',estado:'',regla:'',metodo:'',aging:''});offset=0}
function premiumPanel(kicker,title,subtitle,body,extra=''){return `<section class="fv2-card-panel"><div class="fv2-panel-head"><div><span class="fv2-panel-kicker">${esc(kicker)}</span><h3>${esc(title)}</h3>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${extra}</div>${body}</section>`}
function activateKeyboardButtons(){document.querySelectorAll('[role="button"][tabindex="0"]').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}))}

export async function renderFinancePremium(){
  styles();setMainHtml('<div class="loading-card">Cargando Finanzas Premium…</div>');
  try{
    const [F,D,R]=await Promise.all([flags(),dash(),dict()]);
    if(!F.finance_v2_enabled||!F.finance_dashboard_v2_enabled)throw Error('FINANCE_V2_DISABLED');
    if(Number(D.analytics_version||0)<150)throw Error('FINANCE_ANALYTICS_BACKEND_REQUIRED');
    const [H,Q,P]=await Promise.all([
      F.finance_reports_enabled?reportList():Promise.resolve([]),
      tab==='automations'?qaStatus().catch(()=>null):Promise.resolve(null),
      tab==='automations'?pilotStatus().catch(()=>null):Promise.resolve(null)
    ]);
    const actions=`<div class="fv2-actions"><button class="btn btn-primary" id="new-charge">+ Nuevo cargo</button><button class="btn btn-ghost" id="new-rule">Nueva automatización</button><button class="btn btn-ghost" id="pending">Pagos por validar · ${D.pending_validation||0}</button><button class="btn btn-ghost" id="report">Generar informe</button></div>`;
    let content='';
    if(tab==='summary')content=`<div class="fv2-shell">${filtersHtml(R)}${filterContext(R)}${kpis(D.summary,D)}<div class="fv2-dashboard-grid">${premiumPanel('HISTOGRAMA','12 meses · generado, cobrado y pendiente','Pulsa una barra, una serie o un mes para filtrar el detalle.',histogram(D.months))}${premiumPanel('RIESGO','Antigüedad de deuda','Distribución clicable del saldo pendiente.',aging(D.aging))}</div><div class="fv2-breakdowns">${premiumPanel('COMPOSICIÓN','Cargos por categoría','Cada barra filtra el dashboard completo.',categoryBreakdown(D.categories||[]))}${premiumPanel('ACTIVIDAD','Distribución por grupo / disciplina','Atribución según afiliación activa actual.',dimensionBreakdown(D))}</div>${card(`Detalle de cargos · ${D.total_rows||0}`,charges(D.rows)+pagination(D))}</div>`;
    if(tab==='charges')content=`${filtersHtml(R)}${filterContext(R)}${card(`Cargos · ${D.total_rows||0}`,charges(D.rows)+pagination(D))}`;
    if(tab==='automations')content=`${qaPanel(Q,P)}${automation(R)}`;
    if(tab==='payments')content=payments(D.payments||[],R.members);
    if(tab==='receipts')content=receipts(D.receipts||[]);
    if(tab==='reports')content=reportsPanel(F,H,R);
    setMainHtml(`${pageHeader('Finanzas Premium','Dashboard interactivo, automatización y trazabilidad. KOMBAX registra y valida; no procesa dinero.',actions,'Economía')}${tabs()}${D.pending_validation?`<div class="alert alert-warning" style="margin:0 0 14px"><strong>Requiere acción</strong><span>${D.pending_validation} pagos por validar.</span></div>`:''}${content}`);

    for(const [id,k] of [['f-year','year'],['f-month','month'],['f-socio','socio'],['f-grupo','grupo'],['f-disc','disciplina'],['f-cat','categoria'],['f-state','estado'],['f-rule','regla'],['f-method','metodo'],['f-age','aging']])document.getElementById(id)?.addEventListener('change',e=>{filters[k]=e.target.value;offset=0;renderFinancePremium()});
    document.getElementById('f-clear')?.addEventListener('click',()=>{resetFinanceFilters();renderFinancePremium()});
    document.getElementById('fv2-quick-clear')?.addEventListener('click',()=>{resetFinanceFilters();renderFinancePremium()});
    document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-kpi-kind]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.kpiKind,value=b.dataset.kpiFilter||'';if(kind==='clear'){filters.estado='';filters.aging=''}else if(kind==='estado'){filters.estado=filters.estado===value?'':value}else if(kind==='aging'){filters.aging=filters.aging===value?'':value}offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-chart-point]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();filters.month=b.dataset.month||'';filters.estado=b.dataset.state||'';offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-chart-month]').forEach(b=>b.addEventListener('click',()=>{const x=String(b.dataset.chartMonth||'');filters.month=filters.month===x?'':x;offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-hist-month]').forEach(b=>b.addEventListener('click',()=>{filters.month=String(b.dataset.histMonth||'');filters.estado=String(b.dataset.histState||'');offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-series-state]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.seriesState||'';filters.estado=filters.estado===x?'':x;offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-aging]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.aging;filters.aging=filters.aging===x?'':x;offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.category||'';filters.categoria=filters.categoria===x?'':x;offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-breakdown-mode]').forEach(b=>b.addEventListener('click',()=>{breakdownMode=b.dataset.breakdownMode||'groups';renderFinancePremium()}));
    document.querySelectorAll('[data-dimension]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.dimension,id=b.dataset.dimensionId||'';if(kind==='grupo'){filters.grupo=filters.grupo===id?'':id;if(filters.grupo)filters.disciplina=''}else{filters.disciplina=filters.disciplina===id?'':id;if(filters.disciplina)filters.grupo=''}offset=0;renderFinancePremium()}));
    document.querySelectorAll('[data-charge]').forEach(b=>b.addEventListener('click',()=>detail(D.rows.find(x=>String(x.cuota_id)===String(b.dataset.charge)),F.finance_reports_enabled===true)));
    document.getElementById('prev')?.addEventListener('click',()=>{offset=Math.max(0,offset-PAGE);renderFinancePremium()});document.getElementById('next')?.addEventListener('click',()=>{offset+=PAGE;renderFinancePremium()});
    document.getElementById('new-charge')?.addEventListener('click',()=>wizard(R));document.getElementById('new-rule')?.addEventListener('click',()=>newRule(R));document.getElementById('pending')?.addEventListener('click',()=>{tab='payments';renderFinancePremium()});document.getElementById('report')?.addEventListener('click',()=>{tab='reports';renderFinancePremium()});document.getElementById('export')?.addEventListener('click',()=>csv(D.rows));document.getElementById('report-current')?.addEventListener('click',()=>generateReport('vista_actual'));document.getElementById('report-new')?.addEventListener('click',()=>openReportWizard(R));document.getElementById('report-account-current')?.addEventListener('click',()=>generateReport('estado_cuenta',{socio:filters.socio}));document.querySelectorAll('.report-open').forEach(b=>b.addEventListener('click',()=>{const r=H.find(x=>String(x.id)===String(b.dataset.id));if(r)openReportPdf(r)}));document.querySelectorAll('.report-refresh').forEach(b=>b.addEventListener('click',()=>{const r=H.find(x=>String(x.id)===String(b.dataset.id));if(r)generateReport(r.tipo,{source_report_id:r.id})}));document.getElementById('qa-shadow-run')?.addEventListener('click',runQaShadow);document.getElementById('qa-approve')?.addEventListener('click',approveQa);document.getElementById('qa-revoke')?.addEventListener('click',revokeQa);document.querySelectorAll('.sim').forEach(b=>b.addEventListener('click',()=>simulate(b.dataset.id)));document.querySelectorAll('.toggle-rule').forEach(b=>b.addEventListener('click',()=>{const r=R.rules.find(x=>String(x.id)===String(b.dataset.id));if(r)toggleRule(r)}));document.querySelectorAll('.val').forEach(b=>b.addEventListener('click',async()=>{try{await repos.finance.validate(b.dataset.id,'validado');toast('Pago validado');await renderFinancePremium()}catch(e){setError(e)}}));document.querySelectorAll('.rej').forEach(b=>b.addEventListener('click',()=>openForm({title:'Rechazar pago',fields:[{name:'motivo',label:'Motivo',type:'textarea',required:true,full:true}],onSubmit:async v=>{await repos.finance.validate(b.dataset.id,'rechazado',v.motivo);toast('Pago rechazado');await renderFinancePremium()}})));
    document.querySelectorAll('.fv2-view-receipt').forEach(b=>b.addEventListener('click',()=>{const r=(D.receipts||[]).find(x=>String(x.id)===String(b.dataset.receiptId));if(r)openReceipt(r)}));
    activateKeyboardButtons();
  }catch(e){
    if(String(e?.message||e).includes('FINANCE_V2_DISABLED'))throw e;
    setError(e);throw e;
  }
}
